#include <iostream>
#include <vector>
#include <set>
#include <cmath>

using namespace std;

bool verify_condition(const vector<int>& f, int p, int k) {
    for (int index = 0; index < p; ++index) {
        if (f[(k * index) % p] != (k * f[index]) % p) {
            return false;
        }
    }
    return true;
}

int count_configurations(vector<int>& f, int p, int k, int position) {
    if (position == p) {
        return verify_condition(f, p, k) ? 1 : 0;
    }
    int total = 0;
    for (int value = 0; value < p; ++value) {
        f.push_back(value);
        total += count_configurations(f, p, k, position + 1);
        f.pop_back();
    }
    return total;
}

long long compute_result(int p, int k) {
    int total_groups = 0;
    set<int> seen;
    for (int start = 0; start < p; ++start) {
        if (seen.find(start) == seen.end()) {
            total_groups += 1;
        }
        int current = start;
        while (seen.find(current) == seen.end()) {
            seen.insert(current);
            current = (current * k) % p;
        }
    }
    const long long MOD = 1000000007;
    long long exponent = total_groups - (k != 1 ? 1 : 0);
    long long result = 1;
    long long base = p;
    long long exp = exponent;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    int p, k;
    cin >> p >> k;
    cout << compute_result(p, k) << endl;
    return 0;
}

